(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.015+t*0.32)*11;
  const w2x = Math.sin((x+y)*0.009+t*0.15)*8 + Math.cos((x-y)*0.011-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.01+t*0.17)*7 + Math.sin((x+y)*0.012-t*0.14)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 5.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.8],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+1)*60, 0.11, 2.1, 4.2],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75)*50, 0.075, 1.8, 2.0]
  ];
  let aS=0, iS=0, cross=0, pulse=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,ph]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp+ph);
    aS+=wave;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+ph+1.5);
    pulse+=Math.sin(d*f*0.3-t*sp*0.8+ph)*0.3;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2,ph2]=src[j];
      const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross+=Math.sin((d*f-t*sp+ph)-(d2*f2-t*sp2+ph2))*0.15;
    }
  }
  const n=src.length;
  aS/=n; iS/=n; cross/=n; pulse/=n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15
    +Math.sin(sx*0.07+Math.cos(sy*0.05+t)*2+t*1.8)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.35
    +Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const react=Math.tanh((aS-iS*0.65+bg*0.25+spiral+cross)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.2;
  const flow=Math.sin(sx*0.06+Math.sin(sy*0.04+t*0.5)*3+t)*Math.cos(sy*0.05+Math.cos(sx*0.03-t*0.4)*2.5-t*0.7)*0.15;
  const blend=react*0.6+cell*0.15+flow*0.1+pulse*0.15, v=blend*0.5+0.5;
  const pal=[
    [5,10,42],[10,35,75],[15,70,105],[20,120,130],[45,165,140],
    [140,190,110],[210,185,70],[230,140,60],[215,95,65],[180,60,75],
    [120,35,65],[65,18,50],[25,10,38],[5,10,42]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(react*Math.PI)*0.18;
  const edge=Math.abs(react)>0.72?1.12+Math.abs(react)*0.08:1.0;
  const glow=Math.max(0,1-Math.abs(react)*1.3)*0.15;
  const vig=1-Math.sqrt(((x/480-0.5)**2+((y/240-0.5)*1.2)**2))*0.3;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)*vig)|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)*vig)|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*90)*vig)|0
  ];
}
